            << " seq=" << seq
            << " transmission="
            << (entry->resendCount + 1)
            << " sentAt="
            << sentAt.GetSeconds ()
            << std::endl;

  Time wait =
    entry->resendCount >= m_maxNumResend
      ? m_resendTime + m_resendTime
      : m_resendTime;

